#!/usr/bin/env bash
# Generated by MiniMax M3.1 Flash without human creative authorship.
# SPDX-License-Identifier: LGPL-2.0-or-later
#
# Build every Windows artifact the NSIS installer packages, natively on
# Windows, with nothing installed outside the checkout.
#
# Produces:
#   .tools/build-x86/PIMELauncher/PIMELauncher.exe        (i686-msvc)
#   .tools/build-x86/PIMETextService/PIMETextService.dll   (x86)
#   .tools/build-x64/PIMETextService/PIMETextService.dll   (x64)
#   .tools/build-arm64/PIMETextService/PIMETextService_arm64.dll (native ARM64)
#   .tools/build-arm64/PIMETextService/PIMETextService.dll  (ARM64X forwarder)
#
# and stages them in the layout installer/installer.nsi expects:
#   .tools/stage/build/...        x86 launcher + x86 PIMETextService.dll
#   .tools/stage/build64/...      x64 PIMETextService.dll
#   .tools/stage/build_arm64/...  ARM64X forwarder + native ARM64 DLL
#
# Usage (Git Bash on Windows):
#   bash tests/build_windows_artifacts.sh
#
# The compiler is clang-cl and the linker is lld-link, both from the local
# toolchain in .tools/mingw64, against the Windows SDK and CRT that xwin
# splatted into .tools/msvc. No Visual Studio installation is needed.
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
TOOLS="$ROOT/.tools"
CMAKE="$(ls -1 "$TOOLS"/cmake/cmake-*/bin/cmake.exe 2>/dev/null | head -1)"
NINJA="$TOOLS/mingw64/bin/ninja.exe"
STAGE="$TOOLS/stage"
TOOLCHAINS="$ROOT/tests/toolchains"

if [[ -z "$CMAKE" ]]; then
  echo "ERROR: no CMake in $TOOLS/cmake; run tests/install_windows_toolchain.sh." >&2
  exit 1
fi

export RUSTUP_HOME="C:\\Users\\asdf8\\Documents\\PIME\\.tools\\rustup"
export CARGO_HOME="C:\\Users\\asdf8\\Documents\\PIME\\.tools\\cargo"
export PATH="/c/Users/asdf8/Documents/PIME/.tools/cargo/bin:$PATH"
export CARGO_TARGET_I686_PC_WINDOWS_MSVC_LINKER="C:\\Users\\asdf8\\Documents\\PIME\\.tools\\mingw64\\bin\\lld-link.exe"
RUSTC="C:\\Users\\asdf8\\Documents\\PIME\\.tools\\rustup\\toolchains\\stable-x86_64-pc-windows-gnu\\bin\\rustc.exe"

# The Rust launcher links against the MSVC CRT; point it at the splatted SDK.
export LIB="C:\\Users\\asdf8\\Documents\\PIME\\.tools\\msvc\\sdk\\lib\\um\\x86;C:\\Users\\asdf8\\Documents\\PIME\\.tools\\msvc\\sdk\\lib\\ucrt\\x86;C:\\Users\\asdf8\\Documents\\PIME\\.tools\\msvc\\crt\\lib\\x86"

step() { echo; echo "=== $* ==="; }

step "Refreshing source mirror"
bash "$TOOLS/mirror-sources.sh"

step "Configuring and building x86 (PIMETextService + PIMELauncher)"
"$CMAKE" -S "$TOOLS/src-mirror" -B "$TOOLS/build-x86" -G Ninja \
  -DCMAKE_MAKE_PROGRAM="$NINJA" \
  -DCMAKE_TOOLCHAIN_FILE="$TOOLCHAINS/x86.cmake" \
  -DCMAKE_POLICY_VERSION_MINIMUM=3.5 -DCMAKE_BUILD_TYPE=Release \
  "-DRust_COMPILER=$RUSTC" > /dev/null
"$CMAKE" --build "$TOOLS/build-x86" --config Release --target PIMETextService
"$CMAKE" --build "$TOOLS/build-x86" --config Release --target _cargo-build_PIMELauncher

step "Configuring and building x64"
"$CMAKE" -S "$TOOLS/src-mirror" -B "$TOOLS/build-x64" -G Ninja \
  -DCMAKE_MAKE_PROGRAM="$NINJA" \
  -DCMAKE_TOOLCHAIN_FILE="$TOOLCHAINS/x64.cmake" \
  -DCMAKE_POLICY_VERSION_MINIMUM=3.5 -DCMAKE_BUILD_TYPE=Release > /dev/null
"$CMAKE" --build "$TOOLS/build-x64" --config Release --target PIMETextService

step "Configuring and building ARM64"
"$CMAKE" -S "$TOOLS/src-mirror" -B "$TOOLS/build-arm64" -G Ninja \
  -DCMAKE_MAKE_PROGRAM="$NINJA" \
  -DCMAKE_TOOLCHAIN_FILE="$TOOLCHAINS/arm64.cmake" \
  -DCMAKE_POLICY_VERSION_MINIMUM=3.5 -DCMAKE_BUILD_TYPE=Release > /dev/null
"$CMAKE" --build "$TOOLS/build-arm64" --config Release --target PIMETextService

step "Building the ARM64X forwarder"
# Upstream builds this with MSVC's link.exe, which synthesises the ARM64X
# metadata itself; lld-link cannot, so it is handed the metadata objects the
# layout needs instead. See tests/arm64x/build-forwarder.sh for the details.
# It lands next to the native ARM64 DLL, where CMake's own POST_BUILD step
# would have put it.
FWD="$TOOLS/build-arm64/PIMETextService/PIMETextService.dll"
bash "$ROOT/tests/arm64x/build-forwarder.sh" \
  "$TOOLS/src-mirror/PIMETextService/PIMETextService_arm64x_arm64.def" \
  "$TOOLS/src-mirror/PIMETextService/PIMETextService_arm64x_x64.def" \
  "$FWD"

step "Checking the ARM64X forwarder routes to both backends"
bash "$ROOT/tests/arm64x/verify-forwarder.sh" \
  "$FWD" \
  "$TOOLS/build-arm64/PIMETextService/PIMETextService_arm64.dll" \
  "$TOOLS/build-x64/PIMETextService/PIMETextService.dll"

step "Staging artifacts in the layout installer.nsi expects"
rm -rf "$STAGE/build" "$STAGE/build64" "$STAGE/build_arm64"
mkdir -p "$STAGE/build/PIMELauncher" \
         "$STAGE/build/PIMETextService/Release" \
         "$STAGE/build64/PIMETextService/Release" \
         "$STAGE/build_arm64/PIMETextService/Release"

cp "$TOOLS/build-x86/PIMELauncher/PIMELauncher.exe" "$STAGE/build/PIMELauncher/"
cp "$TOOLS/build-x86/PIMETextService/PIMETextService.dll" "$STAGE/build/PIMETextService/Release/"
cp "$TOOLS/build-x64/PIMETextService/PIMETextService.dll" "$STAGE/build64/PIMETextService/Release/"
cp "$TOOLS/build-arm64/PIMETextService/PIMETextService_arm64.dll" \
   "$STAGE/build_arm64/PIMETextService/Release/"
cp "$FWD" "$STAGE/build_arm64/PIMETextService/Release/PIMETextService.dll"

step "Verifying staged artifacts"
for f in \
  "$STAGE/build/PIMELauncher/PIMELauncher.exe" \
  "$STAGE/build/PIMETextService/Release/PIMETextService.dll" \
  "$STAGE/build64/PIMETextService/Release/PIMETextService.dll" \
  "$STAGE/build_arm64/PIMETextService/Release/PIMETextService.dll" \
  "$STAGE/build_arm64/PIMETextService/Release/PIMETextService_arm64.dll"; do
  if [[ ! -f "$f" ]]; then
    echo "MISSING: $f" >&2
    exit 1
  fi
  printf '  %-72s %8s bytes  %s\n' "${f#$ROOT/}" "$(stat -c%s "$f")" \
    "$("$TOOLS/mingw64/bin/llvm-readobj.exe" --file-headers "$f" 2>/dev/null | grep -m1 'Machine:')"
done

echo
echo "==> staged successfully"
